package com.menter.treatmentvault.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.menter.treatmentvault.*
@Composable fun TreatmentScreen(back:()->Unit){val dao=(androidx.compose.ui.platform.LocalContext.current.applicationContext as TreatmentVaultApplication).database.dao();val plans by dao.plans().collectAsState(emptyList());val records by dao.records().collectAsState(emptyList());var tab by remember{mutableIntStateOf(0)};Page("治疗方案与记录",back){TabRow(tab){Tab(tab==0,{tab=0},{Text("方案")});Tab(tab==1,{tab=1},{Text("治疗记录")})};LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){if(tab==0)items(plans){v->Card{Column(Modifier.padding(12.dp)){Text(v.name,style=MaterialTheme.typography.titleMedium);Text("${v.category} · ${v.date}");Text(v.explanation)}}}else items(records){v->Card{Column(Modifier.padding(12.dp)){Text("${v.date} ${v.type}",style=MaterialTheme.typography.titleMedium);Text(v.content);if(v.sideEffects.isNotBlank())Text("反应：${v.sideEffects}")}}}};Text("第一版优先通过更新包导入完整治疗方案/记录；手工编辑表单后续补强。",style=MaterialTheme.typography.bodySmall)} }
